mapper.select:
SELECT id, user_id, receiver_name, receiver_phone, detail_address, is_default, create_time, update_time FROM user_address WHERE user_id = #{userId}
AND (receiver_name LIKE CONCAT('%', #{keyword}, '%') OR receiver_phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY is_default DESC, id ASC

mapper.update:
UPDATE user_address
receiver_name = #{receiverName}, receiver_phone = #{receiverPhone}, detail_address = #{detailAddress}, is_default = #{isDefault},
WHERE id = #{id}
